```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment fetch (approved grant). The result is deliberately ignored,
        // so a failed fetch cannot change the node's output.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&composed.overview)
        );
        let _ = http_client::fetch(&url);

        let kept = composed.entries.iter().filter(|e| e.kept).count();
        let message = format!(
            "Digest {}: {}\n{} entries ({} kept), {} items considered",
            composed.date,
            composed.overview,
            composed.entries.len(),
            kept,
            composed.considered.len()
        );
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

I treated the input's "text" as the digest's `overview`, since `Digest` has no field named `text`. The enrichment fetch uses `fetch`, which returns failures as a value, and its result is discarded, so a failed fetch can't change the output.

